#pragma once

// ============================================================================
//  ForceBridge -- Robosample's DIRECT contract with OpenMM. No DuMM, no Simbody
//  subsystem, no NonBondedMappings gather.
//
//  Contract:
//    Robosample --> OpenMM : per-atom Cartesian positions in Ground (nm)
//    OpenMM     --> Robosample : per-atom Cartesian forces (kJ/mol/nm), which
//                   Robosample reduces to per-body spatial forces itself.
//  Atom order == OpenMM particle order == global/BFS order, so the transfer is
//  an index-free copy; the force->body scatter uses only model.atomBody[a].
//
//  HEADER-ONLY: every method is defined in-class (implicitly inline), so there
//  is exactly one definition across all translation units and no separate
//  ForceBridge.cpp / CMake entry is needed. (The previous declared-only methods
//  produced the `undefined symbol: ForceBridge::setAtomPositionsInGround` link
//  failure at import time.)
// ============================================================================

#include 

#include "OpenMMContext.hpp" // the existing OpenMM singleton (reused, not wrapped)
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "robot_math.hpp"

class ForceBridge {
    public:
    explicit ForceBridge(const RobotModel& model)
        : model_(model) {
    }

    // Robosample -> OpenMM: cache the Ground-frame positions in OpenMM particle
    // order. The actual context->setPositions happens inside OpenMMContext on
    // the next energy/force call (both of those take the position cache).
    void setAtomPositionsInGround(const RobotState& s) {
        const robo::Vec3* p = s.atomPosG();
        posCache_.resize(static_cast(model_.numAtoms));
        for (int a = 0; a < model_.numAtoms; ++a) {
            posCache_[a] = OpenMM::Vec3(p[a][0], p[a][1], p[a][2]);
        }
    }

    // Potential energy from OpenMM for the cached positions [kJ/mol].
    [[nodiscard]] robo::Real calcPotentialEnergy() const {
        return OpenMMContext::get().computePotentialEnergy(posCache_);
    }

    // OpenMM -> Robosample: read per-atom Cartesian forces and assemble per-body
    // spatial forces about each body's origin, expressed in Ground:
    //   bodyForceG[b].linear  += f_a
    //   bodyForceG[b].angular += (r_a - origin_b) x f_a
    // This is the exact reduction the articulated-body solver consumes; it
    // replaces the whole DuMM NonBondedMappings machinery.
    void getForcesFromOpenMM(RobotState& s) const {
        std::vector forces;
        OpenMMContext::get().evaluateForcesFromPositionsCache(posCache_, forces);

        robo::SpatialVec* BF = s.bodyForceG();
        for (int b = 0; b < model_.numBodies; ++b) {
            BF[b] = robo::SpatialVec(robo::Vec3(0), robo::Vec3(0));
        }
        // Generalized (joint) forces. calcUDot reads mobilityForce as the
        // applied per-DOF force (eps = f - H^T z). This model applies forces
        // ONLY as Cartesian atom forces (reduced into bodyForceG above); there
        // are no direct joint torques (Fixman unused), so the generalized force
        // is identically zero. It lives in the arena and is never written
        // elsewhere, so it MUST be cleared here every step -- otherwise
        // calcUDot reads uninitialized slab memory -> garbage udot -> NaN.
        // (Any future Fixman/biasing term should add into this cleared vector
        //  after evaluate() and before calcUDot.)
        robo::Real* mob = s.mobilityForce();
        for (int i = 0; i < model_.nu; ++i) {
            mob[i] = robo::Real(0);
        }
        const robo::Vec3* posG = s.atomPosG();
        const robo::Transform* X_GB = s.X_GB();
        for (int a = 0; a < model_.numAtoms; ++a) {
            const int b = model_.atomBody[a];
            const robo::Vec3 f(forces[a][0], forces[a][1], forces[a][2]);
            const robo::Vec3 r = posG[a] - X_GB[b].p(); // station in Ground, about body origin
            BF[b][1] += f;                              // linear (force)
            BF[b][0] += r % f;                          // angular (moment about origin); SimTK % == cross
        }
    }

    // One full force evaluation: positions then forces (Dynamics-stage realize).
    void evaluate(RobotState& s) {
        setAtomPositionsInGround(s);
        getForcesFromOpenMM(s);
    }

    // Pure-Cartesian world: push positions, run N Verlet steps on device.
    //
    // LIMITATION: OpenMMContext currently exposes no public getter for the
    // post-integration positions (integrateTrajectory reads them into a local
    // and discards them), so s.atomPosG() cannot be refreshed here yet. The
    // Cartesian world therefore needs ONE small OpenMMContext addition -- e.g.
    //   void getPositions(std::vector& out) const; // state.getPositions()
    // -- after which the marked line below copies them back into s. Until then
    // this integrates correctly on device but the host coordinates are stale;
    // the torsional (HMC) and energy-validation paths do not use this method.
    bool integrateTrajectoryOnDevice(RobotState& s, int steps, robo::Real timestep) {
        setAtomPositionsInGround(s);
        // Push the cached positions onto the context (setPositions side effect).
        std::vector scratchForces;
        OpenMMContext::get().evaluateForcesFromPositionsCache(posCache_, scratchForces);

        const bool ok =
            OpenMMContext::get().integrateTrajectory(static_cast(steps), static_cast(timestep));
        // TODO(openmm-getter): refresh host coordinates once OpenMMContext can
        // return post-integration positions:
        //   std::vector out;
        //   OpenMMContext::get().getPositions(out);
        //   robo::Vec3* p = s.atomPosG();
        //   for (int a = 0; a < model_.numAtoms; ++a) p[a] = robo::Vec3(out[a][0], out[a][1], out[a][2]);
        return ok;
    }

    private:
    const RobotModel& model_;
    std::vector posCache_; // OpenMM particle order, nm
};

#pragma once

// ============================================================================
//  MemoryArena — one aligned, contiguous memory slab with a bump pointer.
//
//  Purpose: give each World (live RobotState) and each Replica (compact
//  RobotState) ONE cache-line-aligned block, internally partitioned into SoA
//  arrays. No per-array malloc, no vector growth, no pointer chasing between
//  arrays at run time: every array's offset is fixed at build time.
//
//  OpenMP-future-compatible: every sub-array is 64-byte aligned, so later
//  `#pragma omp simd` / aligned AVX-512 loads are legal without re-layout.
//  We do NOT use OpenMP here.
//
//  Usage:
//    MemoryArena arena;
//    // Phase 1: reserve (no allocation yet) — record offsets.
//    auto qOff   = arena.reserve(nq);
//    auto posOff = arena.reserve(3 * nAtoms);
//    ...
//    arena.commit();                       // single aligned allocation
//    double* q   = arena.ptr(qOff);
//    double* pos = arena.ptr(posOff);
// ============================================================================

#include 
#include 
#include 
#include 

class MemoryArena {
    public:
    static constexpr std::size_t kAlign = 64; // cache line / AVX-512

    MemoryArena() = default;
    ~MemoryArena() {
        std::free(base_);
    }

    MemoryArena(const MemoryArena&) = delete;
    MemoryArena& operator=(const MemoryArena&) = delete;

    MemoryArena(MemoryArena&& o) noexcept
        : base_(o.base_)
        , size_(o.size_)
        , cursor_(o.cursor_)
        , committed_(o.committed_) {
        o.base_ = nullptr;
        o.size_ = 0;
        o.cursor_ = 0;
        o.committed_ = false;
    }
    MemoryArena& operator=(MemoryArena&& o) noexcept {
        if (this != &o) {
            std::free(base_);
            base_ = o.base_;
            size_ = o.size_;
            cursor_ = o.cursor_;
            committed_ = o.committed_;
            o.base_ = nullptr;
            o.size_ = 0;
            o.cursor_ = 0;
            o.committed_ = false;
        }
        return *this;
    }

    // A handle is just a byte offset into the slab (stable across the program).
    using Handle = std::size_t;

    // Reserve space for `count` T's, 64-byte aligned. Returns a handle.
    // Call only before commit().
    template 
    Handle reserve(std::size_t count) {
        if (committed_) {
            throw std::logic_error("MemoryArena::reserve after commit");
        }
        const std::size_t off = alignUp(cursor_, kAlign);
        cursor_ = off + count * sizeof(T);
        return off;
    }

    // Allocate the single aligned block. Idempotent guard.
    void commit() {
        if (committed_) {
            return;
        }
        size_ = alignUp(cursor_, kAlign);
        if (size_ == 0) {
            size_ = kAlign;
        }
        base_ = static_cast(std::aligned_alloc(kAlign, size_));
        if (base_ == nullptr) {
            throw std::bad_alloc();
        }
        committed_ = true;
    }

    // Typed pointer into the committed slab. Aligned to kAlign by construction.
    template 
    [[nodiscard]] T* ptr(Handle h) const noexcept {
        return reinterpret_cast(base_ + h);
    }

    [[nodiscard]] std::size_t bytes() const noexcept {
        return size_;
    }
    [[nodiscard]] bool committed() const noexcept {
        return committed_;
    }

    private:
    static std::size_t alignUp(std::size_t n, std::size_t a) noexcept {
        return (n + (a - 1)) & ~(a - 1);
    }

    std::byte* base_ = nullptr;
    std::size_t size_ = 0;
    std::size_t cursor_ = 0;
    bool committed_ = false;
};

// ----------------------------------------------------------------------------
//  Span — a non-owning typed view over a slab region. Lets engine code take
//  flat `double* __restrict` loops over arena arrays with no abstraction cost.
// ----------------------------------------------------------------------------
template 
struct SlabSpan {
    T* data = nullptr;
    std::size_t n = 0;
    [[nodiscard]] T& operator[](std::size_t i) const noexcept {
        return data[i];
    }
    [[nodiscard]] T* begin() const noexcept {
        return data;
    }
    [[nodiscard]] T* end() const noexcept {
        return data + n;
    }
    [[nodiscard]] std::size_t size() const noexcept {
        return n;
    }
};

