#include "OpenMM.h"
#include "TopologyElements.hpp"

// Thin Robosample-owned wrapper around a single OpenMM System/Context. It is a
// process-wide singleton: there is exactly one OpenMM system for the whole run,
// built from the (SoA) SystemTopology.
//
// NOTE: the previous revision contained a bad find/replace that turned every
// OpenMM library type (OpenMM::System, OpenMM::Vec3, ...) into OpenMMContext::*.
// Those are restored to OpenMM:: here; only the wrapper's own methods are
// qualified OpenMMContext::.
class OpenMMContext {
    public:
    static auto get() -> OpenMMContext& {
        static OpenMMContext omm;
        return omm;
    }

    auto initialize(const SystemTopology& systemTopology) -> bool;

    void shutdown() {
        integrator.reset();
        context.reset();
        system.reset();
        forceGroupLabels.clear();
        initialized = false;
    }

    void setVelocitiesToTemperature(double temperature, int seed) {
        ensureInitialized();
        context->setVelocitiesToTemperature(temperature, seed);
    }

    [[nodiscard]] auto getPotentialEnergy() const -> double {
        ensureInitialized();
        return potentialEnergy;
    }

    [[nodiscard]] auto getKineticEnergy() const -> double {
        ensureInitialized();
        return kineticEnergy;
    }

    // Potential energy of a single force group [kJ/mol], tagged with the OpenMM
    // force-class name so the Python validation side can line groups up by name
    // (the names match OpenMM's force class names: "NonbondedForce", ...).
    struct ForceGroupEnergy {
        int group = 0;
        std::string name;
        double energy = 0.0; // kJ/mol
    };

    // Controls whether each Force is put in its own OpenMM force group during
    // initialize(). Off by default (all forces share group 0, the historical
    // behaviour). MUST be called BEFORE initialize(): force groups are assigned
    // while the System is being built, so flipping this afterwards has no effect
    // until the next initialize().
    void setSeparateForceGroups(bool enabled) {
        separateForceGroups = enabled;
    }
    [[nodiscard]] auto getSeparateForceGroups() const -> bool {
        return separateForceGroups;
    }

    // Validation entry point: set the given Ground-frame positions on the
    // context and return the potential energy [kJ/mol]. Used to compare this
    // C++ OpenMM build against the Python OpenMM build for the same structure.
    auto computePotentialEnergy(const std::vector& positions) -> double;

    // Same as computePotentialEnergy, but also returns the per-force-group
    // breakdown. .first is the total PE [kJ/mol] (sum over all groups); .second
    // lists one entry per force group. When separate force groups are disabled
    // the breakdown is a single entry (group 0, name "All") equal to the total.
    auto computePotentialEnergyByGroup(const std::vector& positions)
        -> std::pair<double, std::vector>;

    // Direct per-atom force transfer: set positions, read per-atom Cartesian
    // forces. No DuMM, no index gather (atom index == OpenMM particle index).
    void evaluateForcesFromPositionsCache(const std::vector& positions,
                                          std::vector& outForces) const;

    auto integrateTrajectory(int steps, double timeStepInPicoseconds) -> bool;

    auto computePeriodicBoxVectors_Context(double a_length,
                                           double b_length,
                                           double c_length,
                                           double alpha,
                                           double beta,
                                           double gamma)
        -> std::tuple;

    private:
    OpenMMContext() = default;

    void ensureInitialized() const {
        if (!initialized) {
            throw std::runtime_error(
                "OpenMM subsystem not initialized. Call OpenMMContext::initialize() before "
                "using any other functions.");
        }
    }

    // Force builders. OpenMM takes ownership of each Force* once it is passed
    // to System::addForce, hence the raw owning pointers (idiomatic OpenMM).
    [[nodiscard]] auto createNonbondedForce(const SystemTopology& systemTopology) -> OpenMM::NonbondedForce*;
    [[nodiscard]] auto createGBSAOBCForce(const SystemTopology& systemTopology) -> OpenMM::GBSAOBCForce*;
    [[nodiscard]] auto createCustomNonbondedForce(const SystemTopology& systemTopology)
        -> OpenMM::CustomNonbondedForce*;
    [[nodiscard]] auto createHarmonicBondForce(const SystemTopology& systemTopology)
        -> OpenMM::HarmonicBondForce*;
    [[nodiscard]] auto createHarmonicAngleForce(const SystemTopology& systemTopology)
        -> OpenMM::HarmonicAngleForce*;
    [[nodiscard]] auto createPeriodicTorsionForce(const SystemTopology& systemTopology)
        -> OpenMM::PeriodicTorsionForce*;
    [[nodiscard]] auto createImproperHarmonicTorsionForce(const SystemTopology& systemTopology)
        -> OpenMM::CustomTorsionForce*;
    [[nodiscard]] auto createCMAPTorsionForce(const SystemTopology& systemTopology)
        -> OpenMM::CMAPTorsionForce*;
    [[nodiscard]] auto createUreyBradleyForce(const SystemTopology& systemTopology)
        -> OpenMM::HarmonicBondForce*;

    std::unique_ptr context;
    std::unique_ptr system;
    std::unique_ptr integrator;

    std::size_t numAtoms = 0;
    double potentialEnergy = 0;
    double kineticEnergy = 0;

    // When true, each Force gets its own force group in initialize(), enabling
    // a per-term energy breakdown via computePotentialEnergyByGroup().
    bool separateForceGroups = false;

    // (group index, OpenMM force-class name) recorded as forces are added in
    // initialize(). Empty unless separateForceGroups was set before init.
    std::vector<std::pair> forceGroupLabels;

    bool enforcePeriodicBox = false;
    bool initialized = false;
};

#pragma once

// ============================================================================
//  RobotEngine — the SimTK-free dynamics, living in Robosample. Operates on a
//  (const RobotModel&, RobotState&) pair. NO SimTK subsystem/handle types, NO
//  vtables: mobilizer identity is a `switch (model.bodyJoint[b])`, replacing
//  Simbody's RigidBodyNode virtual dispatch.
//
//  EVERY method here is a *faithful port* of a named Simbody routine. The point
//  is behavior preservation: build this beside Simbody, diff each operator to
//  tolerance over random states and every mobilizer type, and only then remove
//  Simbody (MIGRATION_DESIGN.md §6). Bodies are left unimplemented here on
//  purpose — they are transcriptions, not inventions, and must be validated.
//
//  Tree order invariant: model.bodyParent[b] < b. Outward sweep = forward
//  iteration over bodies; inward sweep = reverse iteration. Ground == body 0.
//
//  OpenMP-future: all sweeps are index loops over contiguous SoA; level-parallel
//  variants can later use model.bodyLevel without changing the math. No OpenMP
//  now.
// ============================================================================

#include "ForceBridge.hpp"
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "robot_math.hpp"

class RobotEngine {
    public:
    // ---- KINEMATICS --------------------------------------------------------
    // Port of RigidBodyNodeSpec::realizePosition (RigidBodyNodeSpec.h) +
    // per-joint calcAcrossJointVelocityJacobian (H_FM) + calcBodyTransforms.
    // Outward sweep. Fills X_FM, X_PB, X_GB, Phi, H_FM, H_PB_G, and then the
    // per-atom Ground positions/stations (port of
    // DuMMForceFieldSubsystemRep::realizeSubsystemPositionImpl).
    static void realizePosition(const RobotModel& m, RobotState& s);

    // Port of RigidBodyNodeSpec::realizeVelocity. Fills V_FM, V_GB, Coriolis
    // (AC_GB precursor), gyroscopic terms. Outward sweep.
    static void realizeVelocity(const RobotModel& m, RobotState& s);

    // q-dot from u: per-joint calcQDot / multiplyByN (quaternion coupling for
    // Ball/Free lives here). Port of RigidBodyNodeSpec::calcQDot.
    static void calcQDot(const RobotModel& m, const RobotState& s, robo::Real* qdotOut);
    static void calcQDotDot(const RobotModel& m, RobotState& s);

    // ---- ARTICULATED-BODY DYNAMICS ----------------------------------------
    // Port of realizeArticulatedBodyInertiasInward (RigidBodyNodeSpec.cpp).
    // Inward sweep. Fills P, PPlus, D, DI, G.
    static void realizeArticulatedBodyInertias(const RobotModel& m, RobotState& s);

    // Forward dynamics: forces -> udot. Port of calcUDotPass1Inward (Z, eps,
    // zPlus) + calcUDotPass2Outward (udot, A_GB). Requires bodyForceG +
    // mobilityForce already set (ForceBridge + optional Fixman).
    static void calcUDot(const RobotModel& m, RobotState& s);

    // ---- MASS-MATRIX OPERATORS (no M ever formed) -------------------------
    // Port of multiplyByMInvPass1Inward + multiplyByMInvPass2Outward.
    static void multiplyByMInv(const RobotModel& m, RobotState& s, const robo::Real* in, robo::Real* out);

    // Port of multiplyBySqrtMInvPassOutward (+ inward companion). Used for HMC
    // velocity seeding: u = sqrt(boostRT) * sqrtMInv * gaussian.
    static void multiplyBySqrtMInv(const RobotModel& m, RobotState& s, const robo::Real* in, robo::Real* out);

    // Port of SimbodyMatterSubsystemRep::calcKineticEnergy ( 1/2 u^T M u ).
    static robo::Real calcKineticEnergy(const RobotModel& m, const RobotState& s);

    // ---- INTEGRATOR -------------------------------------------------------
    // Port of VerletIntegrator.cpp::attemptDAEStep, FIXED step. Sequence:
    //   q1 = q0 + h*qdot0 + (h^2/2)*qdotdot0
    //   u1_est = u0 + h*udot0
    //   realizePosition; projectQ (== quaternion renormalization ONLY, no
    //     constraints — see MIGRATION_DESIGN.md §1/§4.3)
    //   realizeVelocity; forces; calcUDot
    //   implicit-trapezoid refine u (<=10 iters): u1 = u0 + (h/2)(udot0+udot1)
    // Advances state by exactly one step h.
    static void verletStep(const RobotModel& m, RobotState& s, ForceBridge& bridge, robo::Real h);

    // Drives verletStep until t_end. Port of TimeStepper::stepTo for the fixed-
    // step velocity-Verlet path Robosample uses. Returns success.
    static bool stepTo(const RobotModel& m, RobotState& s, ForceBridge& bridge, robo::Real tEnd);

    // ---- TRANSFER: internal q/u -> Cartesian (accept path) ----------------
    // Port of the accept-branch loop in HMCSampler::sampleIteration:
    //   atomPosG[a] = X_GB[body].p + X_GB[body].R * station_B[a]
    // Assumes realizePosition has run.
    static void fillAtomPositionsFromBodies(const RobotModel& m, RobotState& s);

    // ---- TRANSFER: Cartesian targets -> internal state --------------------
    // ---- quaternion projection (no-constraint Verlet projection) ----------
    // Renormalizes each quaternion q-block listed in model.quaternionQStart.
    static void normalizeQuaternions(const RobotModel& m, RobotState& s);

    // NOTE: the per-joint kernels (X_FM, H_FM, qdot, qddot) are transcribed
    // inline inside realizePosition / realizeVelocity / calcQDot[Dot] rather
    // than as separate static helpers, so there are no extra symbols to define.
};

#pragma once

// ============================================================================
//  robot_math.hpp — the ONE place the dynamics engine names its linear-algebra
//  value types. Everything else (RobotModel, RobotState, RobotEngine) uses
//  these aliases, never SimTK names directly.
//
//  WHY a typedef layer (see MIGRATION_DESIGN.md §2, Q6):
//  The slow part of SimTK is the *subsystem/handle* machinery (MobilizedBody,
//  SimbodyMatterSubsystem, State) — PIMPL + vtables + staged caches. The small
//  *value* types (Vec3, Mat33, Rotation, Transform, SpatialVec, Articulated
//  Inertia, Quaternion) are header-only, vtable-free, POD-like, and are the
//  physics. Re-deriving them by hand is pure numeric risk for zero speedup.
//
//  So in Phase 0–5 we KEEP SimTK's value types behind these aliases and remove
//  only the heavy machinery. When/if you want SimTK fully gone (Q6), drop in
//  in-house POD equivalents HERE and the engine is unaffected.
//
//  None of these types has a vtable; all are trivially copyable and slab-safe.
// ============================================================================

#include "simbody/internal/common.h" // SpatialVec, SpatialMat, etc.

#include "SimTKcommon.h" // Vec, Mat, Rotation, Transform, SymMat

namespace robo {

using Real = SimTK::Real; // double

using Vec3 = SimTK::Vec3;
using Mat33 = SimTK::Mat33;
using SymMat33 = SimTK::SymMat33;
using Rotation = SimTK::Rotation;
using Transform = SimTK::Transform; // rotation + translation (X_AB)
using Quaternion = SimTK::Quaternion;
using UnitVec3 = SimTK::UnitVec3;

// Spatial (6-vector) algebra used throughout the Articulated Body Algorithm.
using SpatialVec = SimTK::SpatialVec; // Vec2: [angular; linear]
using SpatialMat = SimTK::SpatialMat; // 6x6 in 2x2 of Mat33
using Inertia = SimTK::Inertia;       // 2nd mass moment about a point, in a frame
using MassProperties = SimTK::MassProperties;
using ArticulatedInertia = SimTK::ArticulatedInertia; // P (Jain), 6x6 symmetric-ish
using SpatialInertia = SimTK::SpatialInertia;
using UnitInertia = SimTK::UnitInertia;

// Rigid spatial shift operator Phi (parent->child), a.k.a. SimTK PhiMatrix.
using PhiMatrix = SimTK::PhiMatrix;

// Index typedefs kept as plain ints in the SoA; we don't use SimTK index types
// in the slab to keep it POD and binary-stable.

// Compile-time guarantees that these are slab-safe (no vtable, trivially copy).
static_assert(sizeof(Vec3) == 3 * sizeof(Real), "Vec3 layout");
static_assert(sizeof(SpatialVec) == 6 * sizeof(Real), "SpatialVec layout");
// The MemoryArena hands out raw aligned storage that it frees without running
// element destructors, and the engine initialises every slot by assignment
// before first read. The real requirement is therefore trivial DESTRUCTIBILITY
// (these SimTK value types are fixed arrays of Real: no heap, no vtable), not
// trivial copyability (SimTK provides user-defined copy ops, so that would and
// did fail).
static_assert(std::is_trivially_destructible::value, "Vec3 trivially destructible");
static_assert(std::is_trivially_destructible::value, "Transform trivially destructible");
static_assert(std::is_trivially_destructible::value, "SpatialVec trivially destructible");

} // namespace robo

#pragma once

// ============================================================================
//  RobotModel — the immutable, precomputed, per-World graph. Built ONCE in
//  World::build() from the SoA SystemTopology + this world's per-bond
//  mobilities. Never rebuilt on a coordinate transfer (this is what kills the
//  per-transfer realizeTopology() cost in the current code).
//
//  This is a faithful SoA port of what World currently precomputes across
//  decomposeRigidUnits / buildFrameGraph / modelOneCompound / modelTopologies,
//  with the joint frames and mass properties stored as CONSTANTS rather than
//  Simbody topology-stage defaults.
//
//  SoA, no vtables. Joint identity is an enum per body, branched in the engine
//  (replacing Simbody's RigidBodyNode virtual dispatch).
//
//  Tables here are built once and never resized; std::vector is fine. They can
//  later be frozen into a MemoryArena alongside RobotState if profiling wants
//  the sweep inputs cache-packed — the engine reads them through pointers only.
// ============================================================================

#include 
#include 

#include "robot_math.hpp"

// Joint type per body. Mirrors the mobility->MobilizedBody mapping in
// World::modelOneCompound. NO SimTK enum on the hot path.
enum class JointType : std::uint8_t {
    Weld = 0,    // 0 dof
    Pin,         // 1 dof  (Torsion bond mobility)
    Slider,      // 1 dof
    Cylinder,    // 2 dof
    BendStretch, // 2 dof
    Translation, // 3 dof  (Cartesian)
    Ball,        // 3 dof, q = 4 (quaternion) by default
    SphericalCoords,
    FreeLine, // 5 dof
    Free,     // 6 dof, q = 7 (quaternion + translation)
};

// How a molecule's root body attaches to Ground (mirrors SimTK::RootMobility).
// RootMobility is the SAME enum the topology + Python bindings already use
// (SimTK::RootMobility, defined in molmodel CompoundSystem.h with
// Free=0,Cartesian=1,Weld=2,FreeLine=3,Ball=4,Pin=5). We forward-declare it
// (opaque scoped enum with fixed underlying type == a complete type) and alias
// it so the engine shares ONE enum with the bound topology -- no parallel
// values, and no Molmodel header pulled into this foundational file. The full
// definition arrives via TopologyElements.hpp in the .cpp that need enumerators.
namespace SimTK {
enum class RootMobility : std::uint8_t;
}
using RootMobility = SimTK::RootMobility;

// ----------------------------------------------------------------------------
//  INDEX / ORDER CONVENTIONS (must match python/robosample/molecule_prototype.py
//  and z_matrix.py exactly -- see MIGRATION_PLAN_v2_corrections.md Part B 5/6):
//   * Atoms arrive in BFS/compound order from the root (compound 0 == root).
//     The array position IS the atom index; Molmodel cAIx is retired.
//   * Bonds are oriented PARENT->CHILD (root-ward first):  bondsI=parent,
//     bondsJ=child. Ring-closing bonds are flagged (transmitted explicitly)
//     and are NEVER tree edges (skipped in decomposeRigidUnits/buildFrameGraph).
//   * Angles oriented i->k (j center); proper torsions oriented i->l; all
//     root-ward-first, matching Python.
//   * Z-MATRIX uses the standard BAT convention and is the OPPOSITE direction:
//     zI = atom PLACED; zJ/zK/zL = back-references TOWARD root
//     (parent / grandparent / great-grandparent). BAT = dist(zI,zJ),
//     angle(zI,zJ,zK), dihedral(zI,zJ,zK,zL). -1 sentinels in leading rows.
//   * Frame-graph ancestry names: self / parent / grandParent (root-ward).
//     (refChild only exists if the legacy A1 orientation switch is kept.)
// ----------------------------------------------------------------------------
struct RobotModel {
    // ---- system sizes ------------------------------------------------------
    int numBodies = 0; // includes Ground == body 0
    int numAtoms = 0;
    int nq = 0; // total generalized coordinates (quaternion-inflated)
    int nu = 0; // total generalized speeds (== DOFs)

    // ---- body tree, TOPOLOGICAL ORDER (parent index < child index) ---------
    // Sweeps: inward = reverse iteration, outward = forward iteration.
    std::vector bodyParent;      // [numBodies]   parent body (Ground's parent = -1)
    std::vector bodyLevel;       // [numBodies]   depth from Ground (for future level-parallel sweeps)
    std::vector bodyJoint; // [numBodies]
    std::vector bodyRootAtom;    // [numBodies]   the inboard ("root") atom of this body
    std::vector bodyChildrenBeg; // [numBodies]   CSR into bodyChildren
    std::vector bodyChildrenEnd; // [numBodies]
    std::vector bodyChildren;    // flattened children, CSR

    // ---- generalized-coordinate offsets ------------------------------------
    std::vector bodyQIndex;   // [numBodies] first q of this body
    std::vector bodyNQ;       // [numBodies] number of q (4 or 7 if quaternion)
    std::vector bodyUIndex;   // [numBodies] first u of this body
    std::vector bodyNU;       // [numBodies] number of u == dof
    std::vector bodyUSqIndex; // [numBodies] offset into the dof*dof DI pool
    int nuSq = 0;                  // sum of dof^2 over bodies (DI pool size)
    // q-slots that are quaternions and must be renormalized each Verlet step
    // (port of the no-constraint q-projection). Stored as (qStart) of each quat.
    std::vector quaternionQStart; // q index where a 4-wide quaternion begins

    // ---- static joint frames (CONSTANT once built) -------------------------
    // X_PF: inboard frame fixed on the PARENT body. X_BM: outboard frame fixed
    // on THIS body. These define the mobilizer; in the current code they were
    // Simbody topology defaults rewritten every transfer — here they are fixed.
    std::vector X_PF; // [numBodies]
    std::vector X_BM; // [numBodies]

    // ---- mass properties (RECOMPUTED every transfer; about body origin)
    std::vector bodyMass;  // [numBodies]
    std::vector bodyCom_B; // [numBodies] center of mass in body frame
    std::vector
        bodyUnitInertia_B; // [numBodies] unit inertia about body origin, body frame

    // ---- atom <-> body maps ------------------------------------------------
    std::vector atomBody;             // [numAtoms]  body index of each atom
    std::vector atomMass;      // [numAtoms]  per-atom mass (Daltons), constant
    std::vector atomStation_B; // [numAtoms]  atom in body frame (per transfer)
    std::vector atomDummIndex;        // [numAtoms]  DuMM atom index (for OpenMM mapping)
    std::vector atomCompoundIndex;    // [numAtoms]  cAIx (analysis / IO compatibility)
    std::vector bodyAtomsBeg;         // [numBodies] CSR into a body-sorted atom list
    std::vector bodyAtomsEnd;         // [numBodies]
    std::vector bodyAtoms;            // flattened atoms per body, CSR

    // ---- frame graph (your existing Cartesian->frame kernel, kept verbatim) -
    struct FrameGraph {
        int totalAtoms = 0;
        std::vector topoOffset;                              // [numTopologies+1]
        std::vector g_self, g_parent, g_gparent, g_refChild; // full-geometry bucket
        std::vector f_self, f_parent;                        // fallback bucket
        std::vector r_self;                                  // roots
    } frameGraph;

    // ---- OpenMM force->body reduction (NO NonBondedMappings) ----------------
    // DuMM's NonBondedMappings (dummAtomIndex/includedAtomIndex/bodyIndex/
    // bodyStart) is DROPPED. Atom index == OpenMM particle index == SoA
    // position, so positions hand over with no gather. The force->body
    // reduction needs ONLY atomBody[a] (above): scatter into the small
    // bodyForce array (numBodies SpatialVecs, hot in L1). The body-sorted
    // atom CSR (bodyAtoms/bodyAtomsBeg/End, above) is OPTIONAL and only used
    // if a very large single robot wants a strict sequential reduction.

    // ---- z-matrix rows (BAT) ----------------------------------------------
    std::vector zI, zJ, zK, zL; // [numZRows]; -1 sentinels in leading rows
    int numZRows = 0;

    // ---- convenience -------------------------------------------------------
    [[nodiscard]] bool isQuaternionBody(int b) const {
        return bodyJoint[b] == JointType::Ball || bodyJoint[b] == JointType::Free;
    }
};

#pragma once

// ============================================================================
//  RobotState - the single aligned slab holding every per-step quantity, SoA.
//  Replaces SimTK::State + the SBTree*Cache caches (Simbody01/Simbody/src/
//  SimbodyTreeState.h). Field names track those caches so the engine port can
//  be diffed 1:1 against Simbody.
//
//  H_FM / H / G are stored as SpatialVec COLUMNS: column j of a body lives at
//  index (bodyUIndex + j). One SpatialVec == 2 Vec3, so an array of `nu`
//  SpatialVec is exactly the 2*nu Vec3 hinge storage Simbody uses.
//
//  DI (the dof x dof articulated hinge inverse) lives in a flat Real pool of
//  size model.nuSq, addressed by model.bodyUSqIndex[b] (row-major dof x dof).
// ============================================================================

#include "MemoryArena.hpp"
#include "RobotModel.hpp"
#include "robot_math.hpp"

struct EnergySnapshot {
    robo::Real pe = 0;
    robo::Real ke = 0;
    robo::Real fixman = 0;
    robo::Real logSineSqrGamma2 = 0;
    robo::Real total = 0;
};

class RobotState {
    public:
    RobotState() = default;

    void allocateFull(const RobotModel& m) {
        nq_ = m.nq;
        nu_ = m.nu;
        nAtoms_ = m.numAtoms;
        nBodies_ = m.numBodies;
        nZRows_ = m.numZRows;
        nuSq_ = m.nuSq;

        hQ_ = arena_.reserve(nq_);
        hU_ = arena_.reserve(nu_);
        hQDot_ = arena_.reserve(nq_);
        hUDot_ = arena_.reserve(nu_);
        hQDotDot_ = arena_.reserve(nq_);

        hAtomPosG_ = arena_.reserve(nAtoms_);
        hAtomStationG_ = arena_.reserve(nAtoms_);

        hX_GB_ = arena_.reserve(nBodies_);
        hX_FM_ = arena_.reserve(nBodies_);
        hX_PB_ = arena_.reserve(nBodies_);
        hPhi_ = arena_.reserve(nBodies_);
        hMk_G_ = arena_.reserve(nBodies_);
        hComG_ = arena_.reserve(nBodies_);
        hH_FM_ = arena_.reserve(nu_);
        hH_ = arena_.reserve(nu_);
        hV_FM_ = arena_.reserve(nBodies_);
        hV_PB_G_ = arena_.reserve(nBodies_);
        hV_GB_ = arena_.reserve(nBodies_);
        hA_GB_ = arena_.reserve(nBodies_);
        hGyro_ = arena_.reserve(nBodies_);
        hCoriolisA_ = arena_.reserve(nBodies_);
        hMobCoriolisA_ = arena_.reserve(nBodies_);

        hP_ = arena_.reserve(nBodies_);
        hPPlus_ = arena_.reserve(nBodies_);
        hG_ = arena_.reserve(nu_);
        hDI_ = arena_.reserve(nuSq_);
        hABCentrifugal_ = arena_.reserve(nBodies_);
        hZ_ = arena_.reserve(nBodies_);
        hZPlus_ = arena_.reserve(nBodies_);
        hEps_ = arena_.reserve(nu_);

        hBodyForceG_ = arena_.reserve(nBodies_);
        hMobilityForce_ = arena_.reserve(nu_);
        hBAT_ = arena_.reserve(nZRows_);

        arena_.commit();
        full_ = true;
    }

    void allocateCompact(const RobotModel& m) {
        nAtoms_ = m.numAtoms;
        nZRows_ = m.numZRows;
        hAtomPosG_ = arena_.reserve(nAtoms_);
        hBAT_ = arena_.reserve(nZRows_);
        arena_.commit();
        full_ = false;
    }

    [[nodiscard]] robo::Real* q() const { return arena_.ptr(hQ_); }
    [[nodiscard]] robo::Real* u() const { return arena_.ptr(hU_); }
    [[nodiscard]] robo::Real* qdot() const { return arena_.ptr(hQDot_); }
    [[nodiscard]] robo::Real* udot() const { return arena_.ptr(hUDot_); }
    [[nodiscard]] robo::Real* qdotdot() const { return arena_.ptr(hQDotDot_); }

    [[nodiscard]] robo::Vec3* atomPosG() const { return arena_.ptr(hAtomPosG_); }
    [[nodiscard]] robo::Vec3* atomStationG() const { return arena_.ptr(hAtomStationG_); }

    [[nodiscard]] robo::Transform* X_GB() const { return arena_.ptr(hX_GB_); }
    [[nodiscard]] robo::Transform* X_FM() const { return arena_.ptr(hX_FM_); }
    [[nodiscard]] robo::Transform* X_PB() const { return arena_.ptr(hX_PB_); }
    [[nodiscard]] robo::PhiMatrix* Phi() const { return arena_.ptr(hPhi_); }
    [[nodiscard]] robo::SpatialInertia* Mk_G() const { return arena_.ptr(hMk_G_); }
    [[nodiscard]] robo::Vec3* comG() const { return arena_.ptr(hComG_); }
    [[nodiscard]] robo::SpatialVec* H_FM() const { return arena_.ptr(hH_FM_); }
    [[nodiscard]] robo::SpatialVec* H() const { return arena_.ptr(hH_); }
    [[nodiscard]] robo::SpatialVec* V_FM() const { return arena_.ptr(hV_FM_); }
    [[nodiscard]] robo::SpatialVec* V_PB_G() const { return arena_.ptr(hV_PB_G_); }
    [[nodiscard]] robo::SpatialVec* V_GB() const { return arena_.ptr(hV_GB_); }
    [[nodiscard]] robo::SpatialVec* A_GB() const { return arena_.ptr(hA_GB_); }
    [[nodiscard]] robo::SpatialVec* gyro() const { return arena_.ptr(hGyro_); }
    [[nodiscard]] robo::SpatialVec* coriolisA() const { return arena_.ptr(hCoriolisA_); }
    [[nodiscard]] robo::SpatialVec* mobCoriolisA() const { return arena_.ptr(hMobCoriolisA_); }

    [[nodiscard]] robo::ArticulatedInertia* P() const { return arena_.ptr(hP_); }
    [[nodiscard]] robo::ArticulatedInertia* PPlus() const { return arena_.ptr(hPPlus_); }
    [[nodiscard]] robo::SpatialVec* G() const { return arena_.ptr(hG_); }
    [[nodiscard]] robo::Real* DI() const { return arena_.ptr(hDI_); }
    [[nodiscard]] robo::SpatialVec* abCentrifugal() const { return arena_.ptr(hABCentrifugal_); }
    [[nodiscard]] robo::SpatialVec* Z() const { return arena_.ptr(hZ_); }
    [[nodiscard]] robo::SpatialVec* zPlus() const { return arena_.ptr(hZPlus_); }
    [[nodiscard]] robo::Real* eps() const { return arena_.ptr(hEps_); }

    [[nodiscard]] robo::SpatialVec* bodyForceG() const { return arena_.ptr(hBodyForceG_); }
    [[nodiscard]] robo::Real* mobilityForce() const { return arena_.ptr(hMobilityForce_); }
    [[nodiscard]] robo::Vec3* BAT() const { return arena_.ptr(hBAT_); }

    [[nodiscard]] int nq() const { return nq_; }
    [[nodiscard]] int nu() const { return nu_; }
    [[nodiscard]] int numAtoms() const { return nAtoms_; }
    [[nodiscard]] int numBodies() const { return nBodies_; }
    [[nodiscard]] bool isFull() const { return full_; }

    EnergySnapshot energy;
    robo::Real time = 0;

    void copyTransferPayloadTo(RobotState& dst) const {
        const robo::Vec3* src = atomPosG();
        robo::Vec3* d = dst.atomPosG();
        for (int i = 0; i < nAtoms_; ++i) {
            d[i] = src[i];
        }
        dst.energy = energy;
    }

    private:
    MemoryArena arena_;
    bool full_ = false;
    int nq_ = 0, nu_ = 0, nAtoms_ = 0, nBodies_ = 0, nZRows_ = 0, nuSq_ = 0;

    using Hnd = MemoryArena::Handle;
    Hnd hQ_{}, hU_{}, hQDot_{}, hUDot_{}, hQDotDot_{};
    Hnd hAtomPosG_{}, hAtomStationG_{};
    Hnd hX_GB_{}, hX_FM_{}, hX_PB_{}, hPhi_{}, hMk_G_{}, hComG_{}, hH_FM_{}, hH_{};
    Hnd hV_FM_{}, hV_PB_G_{}, hV_GB_{}, hA_GB_{}, hGyro_{}, hCoriolisA_{}, hMobCoriolisA_{};
    Hnd hP_{}, hPPlus_{}, hG_{}, hDI_{}, hABCentrifugal_{}, hZ_{}, hZPlus_{}, hEps_{};
    Hnd hBodyForceG_{}, hMobilityForce_{}, hBAT_{};
};

