#include 

#include "CompoundSystem.h"
#include "Molmodel.h"
#include "Simbody.h"

enum NonbondedMethod : std::uint8_t {
    // No cutoff is applied to nonbonded interactions. The full set of N^2 interactions is computed exactly.
    // This necessarily means that periodic boundary conditions cannot be used. This is the default.
    NoCutoff = 0,

    // Interactions beyond the cutoff distance are ignored. Coulomb interactions closer than the cutoff
    // distance are modified using the reaction field method.
    CutoffNonPeriodic,

    // Periodic boundary conditions are used, so that each particle interacts only with the nearest periodic
    // copy of each other particle. Interactions beyond the cutoff distance are ignored. Coulomb interactions
    // closer than the cutoff distance are modified using the reaction field method.
    CutoffPeriodic,

    // Periodic boundary conditions are used, and Ewald summation is used to compute the interaction of each
    // particle with all periodic copies of every other particle.
    Ewald,

    // Periodic boundary conditions are used, and Particle-Mesh Ewald (PME) summation is used to compute the
    // interaction of each particle with all periodic copies of every other particle.
    PME,
};

using CanonicalBond = std::pair;
using CanonicalAngle = std::array;
using CanonicalTorsion = std::array;

[[nodiscard]] static inline std::pair canonicalizeBond(std::size_t i,
                                                                                 std::size_t j) noexcept {
    return {std::min(i, j), std::max(i, j)};
}

[[nodiscard]] static inline auto canonicalizeAngle(std::size_t i, std::size_t j, std::size_t k) noexcept
    -> std::array {
    return {std::min(i, k), j, std::max(i, k)};
}

[[nodiscard]] static inline auto
canonicalizeTorsion(std::size_t i, std::size_t j, std::size_t k, std::size_t l) noexcept
    -> std::array {
    const std::array forward{i, j, k, l};
    const std::array reverse{l, k, j, i};
    return (forward < reverse) ? forward : reverse;
}

struct SystemTopology {
    // -------------------------------------------------------------------------
    // Molecule ranges  -- [begin, end) into each array above; length == numMolecules
    // -------------------------------------------------------------------------

    int numMolecules{0};
    std::vector atomsBegin;
    std::vector atomsEnd;
    std::vector bondsBegin;
    std::vector bondsEnd;
    std::vector anglesBegin;
    std::vector anglesEnd;
    std::vector periodicTorsionsBegin;
    std::vector periodicTorsionsEnd;
    std::vector harmonicTorsionsBegin;
    std::vector harmonicTorsionsEnd;
    std::vector zMatrixBegin;
    std::vector zMatrixEnd;
    std::vector ureyBradleyBegin;
    std::vector ureyBradleyEnd;
    std::vector scaling14Begin;
    std::vector scaling14End;
    std::vector exclusionBegin;
    std::vector exclusionEnd;
    std::vector atomsRootIndex;
    std::vector rootMobilities;

    // -------------------------------------------------------------------------
    // Atom arrays  (BFS order, unit-converted)
    // -------------------------------------------------------------------------

    int numAtoms{0};
    std::vector atomsUniqueName;
    std::vector atomsClassNames;
    std::vector atomsChargedTypeNames;
    std::vector atomsNonbondedIndex;
    std::vector atomsCompoundAtomIndex;    // SimTK::Compound::AtomIndex
    std::vector atomsAtomClassIndex;       // SimTK::DuMM::AtomClassIndex
    std::vector atomsChargedAtomTypeIndex; // SimTK::DuMM::ChargedAtomTypeIndex

    std::vector atomsElementName;
    std::vector atomsElementSymbol;
    std::vector atomsMass;    ///< Mass.                               [daltons]
    std::vector atomsCharge;  ///< Partial charge.                     [e]
    std::vector atomsSigma;   ///< Lennard-Jones sigma (vdW radius).   [nm]
    std::vector atomsEpsilon; ///< Lennard-Jones epsilon (well depth). [kJ/mol]
    std::vector atomsRadius;  ///< GBSA solvent radius.                [nm]
    std::vector atomsScreen;  ///< OBC screening factor.               [dimensionless]
    std::vector atomsX;       ///< x coordinate (reference structure). [nm]
    std::vector atomsY;       ///< y coordinate (reference structure). [nm]
    std::vector atomsZ;       ///< z coordinate (reference structure). [nm]
    std::vector atomsAtomicNumber;
    std::vector atomsNumBondsInvolved;

    std::vector biotypeIndices;

    // -------------------------------------------------------------------------
    // Bond arrays  (BFS order)
    // -------------------------------------------------------------------------

    int numBonds{0};                      ///< Total bonds (tree + ring-closing).
    std::vector bondsI;              ///< BFS index of bond endpoint atom 1.
    std::vector bondsJ;              ///< BFS index of bond endpoint atom 2.
    std::vector bondsMoleculeIndex;  ///< Molecule index this bond belongs to.
    std::vector bondsRingClosing;   ///< Whether this bond is a ring-closing bond.
    std::vector bondsStiffness;   ///< Harmonic force constant.         [kJ/mol/nm^2]
    std::vector bondsEquilibrium; ///< Equilibrium bond length.         [nm]

    // -------------------------------------------------------------------------
    // Angle arrays
    // -------------------------------------------------------------------------

    int numAngles{0};
    std::vector anglesI;
    std::vector anglesJ;
    std::vector anglesK;
    std::vector anglesEquilibrium; ///< Equilibrium angle.               [rad]
    std::vector anglesStiffness;   ///< Harmonic force constant.         [kJ/mol/rad^2]

    // -------------------------------------------------------------------------
    // Periodic torsion arrays
    // -------------------------------------------------------------------------

    int numPeriodicTorsions{0};
    std::vector periodicTorsionsImproper;
    std::vector periodicTorsionsI;
    std::vector periodicTorsionsJ;
    std::vector periodicTorsionsK;
    std::vector periodicTorsionsL;
    std::vector periodicTorsionsN;            ///< Periodicity.
    std::vector periodicTorsionsPhase;     ///< Phase offset.             [rad]
    std::vector periodicTorsionsStiffness; ///< Force constant.           [kJ/mol]

    // -------------------------------------------------------------------------
    // Harmonic torsion arrays
    // -------------------------------------------------------------------------

    int numHarmonicTorsions{0};
    std::vector harmonicTorsionsI;
    std::vector harmonicTorsionsJ;
    std::vector harmonicTorsionsK;
    std::vector harmonicTorsionsL;
    std::vector harmonicTorsionsStiffness; ///< Force constant.           [kJ/mol]
    std::vector harmonicTorsionsPhase;     ///< Equilibrium angle.        [rad]

    // -------------------------------------------------------------------------
    // Z-matrix arrays  (tree-traversal order, rooted at atomsRootIndex)
    // Length n; sentinel value -1 fills inapplicable leading rows (see below).
    // -------------------------------------------------------------------------

    int numZMatrixRows{0};
    std::vector zMatrixI; ///< Global atom index of the atom placed at row r.
    std::vector zMatrixJ; ///< Bond-length reference atom.  Row 0   : -1 (root).
    std::vector zMatrixK; ///< Bond-angle reference atom.   Rows 0-1: -1.
    std::vector zMatrixL; ///< Dihedral reference atom.     Rows 0-2: -1.

    // -------------------------------------------------------------------------
    // Urey-Bradley 1-3 interactions
    // -------------------------------------------------------------------------

    int numUreyBradley{0};
    std::vector ureyBradleyI;              ///< Global index of atom 1 (outer atom of angle i-j-k).
    std::vector ureyBradleyK;              ///< Global index of atom 3 (outer atom of angle i-j-k).
    std::vector ureyBradleyStiffness;   ///< Harmonic force constant. [kJ/mol/nm^2]
    std::vector ureyBradleyEquilibrium; ///< Nominal 1-3 distance.                           [nm]

    // -------------------------------------------------------------------------
    // 1-4 pair scaling
    // -------------------------------------------------------------------------

    int numScaling14{0};
    std::vector scaling14I;                ///< Global index of atom 1 (first atom of dihedral i-j-k-l).
    std::vector scaling14L;                ///< Global index of atom 4 (last  atom of dihedral i-j-k-l).
    std::vector scaling14ChargeProduct; ///< q1*q4 pre-scaled by the 1-4 electrostatic factor.  [e^2]
    std::vector scaling14Epsilon;       ///< Combined LJ well depth.                          [kJ/mol]
    std::vector scaling14Sigma;         ///< Combined LJ radius.                              [nm]

    // -------------------------------------------------------------------------
    // Exclusions
    // -------------------------------------------------------------------------

    int numExclusions{0};
    std::vector exclusionI; ///< Global index of atom 1.
    std::vector exclusionJ; ///< Global index of atom 2.

    // -------------------------------------------------------------------------
    // CMAP torsion arrays
    // -------------------------------------------------------------------------

    int cmapGridSize{0};
    std::vector cmapGridEnergy;

    std::vector cmapTorsionMapIndex;
    std::vector cmapTorsionA1;
    std::vector cmapTorsionA2;
    std::vector cmapTorsionA3;
    std::vector cmapTorsionA4;
    std::vector cmapTorsionB1;
    std::vector cmapTorsionB2;
    std::vector cmapTorsionB3;
    std::vector cmapTorsionB4;

    bool hasNBfix = false;
    int numNBTypes = 0;
    std::vector aCoef;
    std::vector bCoef;

    bool useGBSAOBC2 = false;
    double gbsaSolventDielectric = 78.5;
    double gbsaSoluteDielectric = 1.0;

    NonbondedMethod nonbondedMethod = NonbondedMethod::NoCutoff;
    double nonbondedCutoff = 1.2;

    double thermostatTemperature = 300.0;
    double collisionFrequency = 1.0;
    int seed = 0;
};

#pragma once

// ============================================================================
//  World - reimplemented, SimTK-free. Each World owns ONE robot (immutable
//  RobotModel + live RobotState), a RobotEngine (stateless ops), and a
//  ForceBridge to OpenMM. Two regimes:
//
//    Cartesian world  : the root is free and every bond is rigid is NOT the
//                       point - the Cartesian regime runs plain OpenMM MD on
//                       the device (integrateTrajectoryOnDevice). No ABA. This
//                       matches run.py's add_cartesian_world (timeStep 0.001).
//    Torsional/robotic: internal-coordinate Generalized-Coordinate HMC. The
//                       flexible (Torsion) bonds become Pin joints; everything
//                       else is welded into rigid bodies; the root takes its
//                       RootMobility. Sampling = seed u via sqrt(M^-1), Verlet
//                       stepTo, Metropolis on H = PE + KE.
//
//  Names mirror the originals (generateSamples, sampleIteration, reinitialize,
//  setAtomsLocationsInGround, decomposeRigidUnits, modelOneCompound).
// ============================================================================

#include 
#include 
#include 

#include "ForceBridge.hpp"
#include "RobotEngine.hpp"
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TopologyElements.hpp"
#include "robot_math.hpp"

enum class AcceptRejectMode : std::uint8_t {
    AlwaysAccept = 0,
    MetropolisHastings
};
enum class BondMobility : std::uint8_t {
    Rigid = 0,
    Torsion,
    Free,
    Ball,
    Pin,
    Slider,
    Cylinder,
    BendStretch
};

// Per-bond mobility selection produced by Context::build_flexibilities.
struct Selection {
    std::vector bondMobility; // [numBonds]; default Rigid
};

struct SamplerConfig {
    double timeStep = 0.001;
    int mdSteps = 0;
    int boostMDSteps = 0;
    AcceptRejectMode acceptRejectMode = AcceptRejectMode::AlwaysAccept;
    bool useFixman = false;
};

class World {
    public:
    World(int index, bool cartesian, std::uint32_t seed);

    // Build the immutable RobotModel once from the shared topology + this
    // world's per-bond mobilities, then allocate and seed the live state.
    // (decomposeRigidUnits + modelOneCompound, SimTK-free.)
    void buildModel(const SystemTopology& sys,
                    const Selection& sel,
                    const std::vector& rootMobilities);

    // Python: world.add_sampler(timeStep, mdSteps, boostMDSteps, mode, use_nuts)
    World& add_sampler(double timeStep, int mdSteps, int boostMDSteps, AcceptRejectMode mode, bool use_nuts);

    // Set the live configuration from per-atom Ground coordinates (the transfer
    // currency). For the internal world this also derives q. No realizeTopology.
    void setAtomsLocationsInGround(const std::vector& atomPosG);
    [[nodiscard]] const robo::Vec3* getAtomsLocationsInGround() const {
        return state_.atomPosG();
    }

    // One Gibbs/HMC sample on this world. Returns true if accepted.
    bool generateSample();

    [[nodiscard]] const RobotModel& model() const {
        return model_;
    }
    [[nodiscard]] RobotState& state() {
        return state_;
    }
    [[nodiscard]] int index() const {
        return index_;
    }
    [[nodiscard]] bool isCartesian() const {
        return cartesian_;
    }

    void setTemperature(double T);

    private:
    // --- internal (torsional) HMC pieces (sampleIteration) ---
    void reinitialize(); // seed velocities, record initial energies
    bool metropolis(double Hold, double Hnew);
    double currentTotalEnergy();                       // PE (OpenMM) + KE (engine) [+Fixman]
    void recomputeGeometry(const robo::Vec3* targets); // frames+stations+masses+X_PF/X_BM

    int index_;
    bool cartesian_;
    RobotModel model_;
    RobotState state_;
    ForceBridge bridge_;
    SamplerConfig sampler_;

    double temperature_ = 300.0;
    double RT_ = 0;
    double beta_ = 0;

    std::mt19937_64 rng_;
    std::normal_distribution gaussian_{0.0, 1.0};
    std::uniform_real_distribution uniform_{0.0, 1.0};

    // Saved state for reject (Cartesian: positions; internal: q).
    std::vector savedPosG_;
    std::vector savedQ_;
    double Hold_ = 0;

    // Per-transfer geometry scratch (closed-form atom frames + B cache).
    std::vector frameFlat_; // [numAtoms] F per atom
    std::vector xpcFlat_;   // [numAtoms] B == X_parentBC_childBC
};

