namespace {
constexpr double kBoltzmann_kJ = 0.0083144626; // kJ/mol/K
}

Context::Context(std::string baseName, std::uint32_t seed)
    : baseName(std::move(baseName))
    , seed(seed)
    , rexRng_(seed ^ 0xD1B54A32D192ED03ULL) {
}

void Context::setRootMobility(int moleculeIndex, SimTK::RootMobility mobility) {
    if (moleculeIndex < 0 || moleculeIndex >= static_cast(systemTopology.rootMobilities.size())) {
        throw std::out_of_range("setRootMobility: molecule index " + std::to_string(moleculeIndex)
                                + " out of range (have "
                                + std::to_string(systemTopology.rootMobilities.size()) + " molecules)");
    }
    systemTopology.rootMobilities[moleculeIndex] = mobility;
}

// ---------------------------------------------------------------------------
//  Worlds
// ---------------------------------------------------------------------------
World& Context::addCartesianWorld() {
    const int idx = static_cast(worlds_.size());
    worlds_.push_back(std::make_unique(idx, /*cartesian*/ true, seed));
    worlds_.back()->buildModel(systemTopology, Selection{}, systemTopology.rootMobilities);
    return *worlds_.back();
}

World& Context::addRoboticWorld(const Selection& sel) {
    const int idx = static_cast(worlds_.size());
    worlds_.push_back(std::make_unique(idx, /*cartesian*/ false, seed));
    worlds_.back()->buildModel(systemTopology, sel, systemTopology.rootMobilities);
    return *worlds_.back();
}

Selection Context::buildFlexibilities(const std::optional<std::vector<std::pair>>& bonds,
                                      BondMobility mobility,
                                      bool /*flag*/) {
    Selection sel;
    sel.bondMobility.assign(systemTopology.numBonds, BondMobility::Rigid);

    std::set<std::pair> want;
    if (bonds.has_value()) {
        for (const auto& b : *bonds) {
            want.insert({std::min(b.first, b.second), std::max(b.first, b.second)});
        }
    }

    for (int k = 0; k < systemTopology.numBonds; ++k) {
        if (systemTopology.bondsRingClosing[k]) {
            continue; // ring-closing bonds stay rigid, never constrained
        }
        const int i = systemTopology.bondsI[k];
        const int j = systemTopology.bondsJ[k];
        const bool rotatable =
            systemTopology.atomsNumBondsInvolved[i] >= 2 && systemTopology.atomsNumBondsInvolved[j] >= 2;
        if (!rotatable) {
            continue;
        }
        if (bonds.has_value() && want.count({std::min(i, j), std::max(i, j)}) == 0) {
            continue;
        }
        sel.bondMobility[k] = mobility;
    }
    return sel;
}

// ---------------------------------------------------------------------------
//  Initialize + run
// ---------------------------------------------------------------------------
void Context::initialize(const std::vector& temperatures) {
    temperatures_ = temperatures.empty() ? std::vector{300.0} : temperatures;

    if (!initializeOpenMM()) {
        throw std::runtime_error("Context::initialize: OpenMM initialization failed");
    }

    std::vector ref(systemTopology.numAtoms);
    for (int a = 0; a < systemTopology.numAtoms; ++a) {
        ref[a] = robo::Vec3(systemTopology.atomsX[a], systemTopology.atomsY[a], systemTopology.atomsZ[a]);
    }
    replicaCoords_.assign(temperatures_.size(), ref);
    writeCounter_ = 0;

    // One DCD trajectory per replica: "..dcd". withBox=false
    // (no periodic box is tracked here). The destructor patches NFRAMES/NSTEP.
    dcdWriters_.clear();
    dcdWriters_.reserve(temperatures_.size());
    for (std::size_t r = 0; r < temperatures_.size(); ++r) {
        dcdWriters_.emplace_back();
        dcdWriters_.back().initialize(baseName + "." + std::to_string(r) + ".dcd",
                                      systemTopology.numAtoms,
                                      /*withBox*/ false);
    }
}

void Context::runREX(int equilRounds, int prodRounds, int writeFreq, bool verbose) {
    const int R = static_cast(temperatures_.size());
    const int total = equilRounds + prodRounds;

    for (int round = 0; round < total; ++round) {
        const bool production = round >= equilRounds;

        // Gibbs sweep: each replica runs every world in order.
        for (int r = 0; r < R; ++r) {
            for (auto& w : worlds_) {
                w->setTemperature(temperatures_[r]);
                w->setAtomsLocationsInGround(replicaCoords_[r]);
                w->generateSample();
                const robo::Vec3* p = w->getAtomsLocationsInGround();
                std::copy(p, p + systemTopology.numAtoms, replicaCoords_[r].begin());
            }
        }

        // Replica exchange: adjacent-pair swaps (alternating parity).
        if (R > 1) {
            const int startPair = (round % 2 == 0) ? 0 : 1;
            for (int r = startPair; r + 1 < R; r += 2) {
                const double Ea = openmmPotential(replicaCoords_[r]);
                const double Eb = openmmPotential(replicaCoords_[r + 1]);
                const double betaA = 1.0 / (kBoltzmann_kJ * temperatures_[r]);
                const double betaB = 1.0 / (kBoltzmann_kJ * temperatures_[r + 1]);
                const double delta = (betaA - betaB) * (Ea - Eb);
                if (delta >= 0 || rexUniform_(rexRng_) < std::exp(delta)) {
                    std::swap(replicaCoords_[r], replicaCoords_[r + 1]);
                }
            }
        }

        if (production && writeFreq > 0 && ((round - equilRounds) % writeFreq == 0)) {
            for (int r = 0; r < R; ++r) {
                writeOutputs(r, round, verbose);
            }
            ++writeCounter_;
        }
    }
}

double Context::openmmPotential(const std::vector& coords) {
    std::vector pos;
    pos.reserve(coords.size());
    for (const auto& c : coords) {
        pos.emplace_back(c[0], c[1], c[2]);
    }
    return OpenMMContext::get().computePotentialEnergy(pos);
}

void Context::writeOutputs(int replica, int round, bool verbose) {
    const double pe = openmmPotential(replicaCoords_[replica]);
    const std::string path = baseName + "." + std::to_string(replica) + ".csv";
    std::ofstream out(path, std::ios::app);
    if (out) {
        out << round << "," << replica << "," << temperatures_[replica] << "," << pe << "\n";
    }
    if (verbose) {
        std::printf("[rex] round=%d replica=%d T=%.1f PE=%.4f kJ/mol\n",
                    round,
                    replica,
                    temperatures_[replica],
                    pe);
    }
    // DCD frame: replicaCoords_ are nm in OpenMM/global order; DCD is in
    // Angstrom, so scale by 10 into the reused interleaved scratch buffer.
    // robo::Vec3 is 3 contiguous doubles, but we must scale, so copy rather
    // than reinterpret. The append() gate matches the CSV write cadence.
    if (replica >= 0 && replica < static_cast(dcdWriters_.size())) {
        const auto& coords = replicaCoords_[replica];
        dcdScratch_.resize(static_cast(3 * systemTopology.numAtoms));
        for (int a = 0; a < systemTopology.numAtoms; ++a) {
            dcdScratch_[3 * a + 0] = coords[a][0] * 10.0;
            dcdScratch_[3 * a + 1] = coords[a][1] * 10.0;
            dcdScratch_[3 * a + 2] = coords[a][2] * 10.0;
        }
        dcdWriters_[replica].append(dcdScratch_);
    }
}

// ---------------------------------------------------------------------------
//  OpenMM energy ingestion / validation (preserved verbatim)
// ---------------------------------------------------------------------------
auto Context::initializeOpenMM() -> bool {
    return OpenMMContext::get().initialize(systemTopology);
}

auto Context::calcOpenMMPotentialEnergy() -> double {
    std::vector positions;
    positions.reserve(static_cast(systemTopology.numAtoms));
    for (int i = 0; i < systemTopology.numAtoms; ++i) {
        positions.emplace_back(systemTopology.atomsX[i], systemTopology.atomsY[i], systemTopology.atomsZ[i]);
    }
    return OpenMMContext::get().computePotentialEnergy(positions);
}

auto Context::computePotentialEnergyByGroup()
    -> std::pair<double, std::vector> {
    std::vector positions;
    positions.reserve(static_cast(systemTopology.numAtoms));
    for (int i = 0; i < systemTopology.numAtoms; ++i) {
        positions.emplace_back(systemTopology.atomsX[i], systemTopology.atomsY[i], systemTopology.atomsZ[i]);
    }
    return OpenMMContext::get().computePotentialEnergyByGroup(positions);
}

#include "DCDWriter.hpp"

namespace dcd {

Writer::~Writer() noexcept {
    if (fileFd_ >= 0) {
        finalize();
    }
}

Writer::Writer(Writer&& other) noexcept
    : fileFd_{other.fileFd_}
    , numAtoms_{other.numAtoms_}
    , withBox_{other.withBox_}
    , frameCount_{other.frameCount_}
    , frameBuf_{std::move(other.frameBuf_)}
    , xOffset_{other.xOffset_}
    , yOffset_{other.yOffset_}
    , zOffset_{other.zOffset_}
    , ucOffset_{other.ucOffset_}
    , frameBytes_{other.frameBytes_} {
    other.fileFd_ = -1;
}

auto Writer::operator=(Writer&& other) noexcept -> Writer& {
    if (this != &other) {
        if (fileFd_ >= 0) {
            finalize();
        }
        fileFd_ = other.fileFd_;
        numAtoms_ = other.numAtoms_;
        withBox_ = other.withBox_;
        frameCount_ = other.frameCount_;
        frameBuf_ = std::move(other.frameBuf_);
        xOffset_ = other.xOffset_;
        yOffset_ = other.yOffset_;
        zOffset_ = other.zOffset_;
        ucOffset_ = other.ucOffset_;
        frameBytes_ = other.frameBytes_;
        other.fileFd_ = -1;
    }
    return *this;
}

auto Writer::initialize(const std::string& path, int numAtoms, bool withBox) -> void {
    if (fileFd_ >= 0) {
        throw std::runtime_error{"dcd::Writer: already initialized"};
    }

    this->numAtoms_ = numAtoms;
    this->withBox_ = withBox;

    fileFd_ = ::open(path.c_str(), (O_WRONLY | O_CREAT | O_TRUNC), 0666);
    if (fileFd_ < 0) {
        throw std::runtime_error{"dcd::Writer: cannot open '" + path + '\''};
    }

    buildFrameTemplate();

    const auto hdr = buildHeader();
    writeAll(hdr.data(), static_cast(kHeaderBytes));
}

auto Writer::close() noexcept -> void {
    if (fileFd_ >= 0) {
        finalize();
        fileFd_ = -1;
    }
}

auto Writer::framesWritten() const noexcept -> int {
    return frameCount_;
}

auto Writer::buildFrameTemplate() -> void {
    const auto coordBytes = static_cast(numAtoms_ * 4);
    const int ucBlock = withBox_ ? (4 + 48 + 4) : 0;
    const int coordBlock = (4 + (numAtoms_ * 4) + 4);

    frameBytes_ = ucBlock + (3 * coordBlock);
    frameBuf_.assign(static_cast(frameBytes_), '\0');

    auto poke32 = [this](int off, std::int32_t val) noexcept {
        std::memcpy(frameBuf_.data() + off, &val, sizeof(std::int32_t));
    };

    int off{0};
    if (withBox_) {
        poke32(off, 48);
        off += 4;
        ucOffset_ = off;
        off += 48;
        poke32(off, 48);
        off += 4;
    }
    poke32(off, coordBytes);
    off += 4;
    xOffset_ = off;
    off += (numAtoms_ * 4);
    poke32(off, coordBytes);
    off += 4;

    poke32(off, coordBytes);
    off += 4;
    yOffset_ = off;
    off += (numAtoms_ * 4);
    poke32(off, coordBytes);
    off += 4;

    poke32(off, coordBytes);
    off += 4;
    zOffset_ = off;
    off += (numAtoms_ * 4);
    poke32(off, coordBytes);
}

auto Writer::fillBox(const Box& box) noexcept -> void {
    if (!withBox_) {
        return;
    }
    const double uc[6] = {
        box.sideA,
        std::sin((kHalfPi / 90.0) * (90.0 - box.angleGamma)), // cosAB
        box.sideB,
        std::sin((kHalfPi / 90.0) * (90.0 - box.angleBeta)),  // cosAC
        std::sin((kHalfPi / 90.0) * (90.0 - box.angleAlpha)), // cosBC
        box.sideC,
    };
    std::memcpy(frameBuf_.data() + ucOffset_, uc, 48);
}

auto Writer::deinterleaveCoords(const double* __restrict__ src) noexcept -> void {
    auto* __restrict__ xPtr = reinterpret_cast(frameBuf_.data() + xOffset_);
    auto* __restrict__ yPtr = reinterpret_cast(frameBuf_.data() + yOffset_);
    auto* __restrict__ zPtr = reinterpret_cast(frameBuf_.data() + zOffset_);
    for (int idx{0}; idx < numAtoms_; ++idx) {
        xPtr[idx] = static_cast(src[(3 * idx)]);
        yPtr[idx] = static_cast(src[(3 * idx) + 1]);
        zPtr[idx] = static_cast(src[(3 * idx) + 2]);
    }
}

auto Writer::writeAll(const void* buf, std::size_t size) -> void {
    const auto* ptr = static_cast(buf);
    std::size_t remaining{size};
    while (remaining > 0) {
        const auto written = ::write(fileFd_, ptr, remaining);
        if (written < 0) {
            throw std::runtime_error{"dcd::Writer: write() failed"};
        }
        ptr += written;
        remaining -= static_cast(written);
    }
}

auto Writer::buildHeader() const -> std::array {
    std::array buf{};
    int cur{0};

    auto pI32 = [&](std::int32_t val) noexcept {
        std::memcpy(buf.data() + cur, &val, sizeof(std::int32_t));
        cur += static_cast(sizeof(std::int32_t));
    };
    auto pF32 = [&](float val) noexcept {
        std::memcpy(buf.data() + cur, &val, sizeof(float));
        cur += static_cast(sizeof(float));
    };
    auto pRaw = [&](const void* src, int len) noexcept {
        std::memcpy(buf.data() + cur, src, static_cast(len));
        cur += len;
    };

    //  Block 1: CORD record (84 bytes of content)
    pI32(84);
    pRaw("CORD", 4);
    pI32(0); // [8]  NFRAMES
    pI32(0); // [12] ISTART
    pI32(1); // [16] NSAVC
    pI32(0); // [20] NSTEP
    for (int idx{0}; idx < 4; ++idx) {
        pI32(0);
    } // [24–35] reserved
    pI32(0);                  // [40] NAMNF = 0
    pF32(1.0F);               // [44] DELTA (float, CHARMM style)
    pI32((withBox_) ? 1 : 0); // [48] DCD_HAS_EXTRA_BLOCK
    pI32(0);                  // [52] DCD_HAS_4DIMS = 0
    for (int idx{0}; idx < 7; ++idx) {
        pI32(0);
    } // [56–80] reserved
    pI32(kCharmmVersion); // [84] signals CHARMM format to readers
    pI32(84);             // block-1 record end

    //  Block 2: title strings (2 × 80 bytes)
    pI32(164);
    pI32(2); // NTITLE
    char titleLine[80]{};
    std::strncpy(titleLine, "Created by dcd::Writer", 79);
    pRaw(titleLine, 80);
    char tsLine[80]{};
    const time_t now{std::time(nullptr)};
    std::snprintf(tsLine, 80, "REMARKS Created %.24s", std::ctime(&now));
    pRaw(tsLine, 80);
    pI32(164);

    //  Block 3: atom count
    pI32(4);
    pI32(numAtoms_);
    pI32(4);

    return buf;
}

auto Writer::finalize() noexcept -> void {
    const auto count = static_cast(frameCount_);
    if (::pwrite(fileFd_, &count, sizeof(std::int32_t), kNframesOffset) < 0) {
    }
    if (::pwrite(fileFd_, &count, sizeof(std::int32_t), kNstepOffset) < 0) {
    }
    ::close(fileFd_);
    fileFd_ = -1;
}

